const fs = require("fs");

const { codeFrameColumns } = require("@babel/code-frame");
const cosmiconfigModule = require("cosmiconfig");

function indexToLineColumn(text, index) {
  const lines = text.slice(0, index).split(/\r\n|[\n\r]/);

  return {
    line: lines.length,
    column: lines[lines.length - 1].length + 1,
  };
}

function getJsonErrorPosition(error) {
  const match = error.message.match(/position (\d+)/);

  return match ? Number(match[1]) : 0;
}

function formatJsonErrorMessage(error, content) {
  const position = getJsonErrorPosition(error);
  const location = indexToLineColumn(content, position);
  const codeFrame = codeFrameColumns(
    content,
    {
      start: location,
    },
    {
      highlightCode: false,
    }
  );
  const token = content[position];
  const near = content.trim();
  const message =
    token === undefined
      ? error.message
      : `Unexpected token ${token} in JSON at position ${position} while parsing near '${near}'`;

  return ["", codeFrame, "", message, "", codeFrame, ""].join("\n");
}

function loadJson(filepath, content) {
  try {
    return JSON.parse(content);
  } catch (error) {
    error.message = `JSON Error in ${filepath}: ${formatJsonErrorMessage(
      error,
      content
    )}`;
    throw error;
  }
}

function addJsonLoader(options) {
  options = options || {};

  if (
    options.loaders &&
    Object.prototype.hasOwnProperty.call(options.loaders, ".json")
  ) {
    return options;
  }

  return {
    ...options,
    loaders: {
      ...options.loaders,
      ".json": loadJson,
    },
  };
}

function addCodeFrameToJsonError(error) {
  const match = error.message.match(/^JSON Error in (.*):\n([\s\S]*)$/);

  if (!match || match[2].includes("\n> ")) {
    return error;
